<script>
const $=id=>document.getElementById(id);
let adults=2,children=0,rooms=1,selectedStart=null,selectedEnd=null;
function closePopups(except){['destinationPopup','calendarPopup','guestsPopup'].forEach(x=>{if(x!==except)$(x).classList.add('hidden')})}
$('destinationField').onclick=e=>{if(e.target.closest('.dest-row')||e.target.id==='clearDest')return;closePopups('destinationPopup');$('destinationPopup').classList.toggle('hidden')};
document.querySelectorAll('.dest-row').forEach(r=>r.onclick=()=>{ $('destinationText').textContent=r.dataset.city;$('clearDest').classList.remove('hidden');$('destinationPopup').classList.add('hidden')});
$('clearDest').onclick=e=>{e.stopPropagation();$('destinationText').textContent='Where are you going?';$('clearDest').classList.add('hidden')};
$('dateField').onclick=e=>{if(e.target.closest('.day'))return;closePopups('calendarPopup');$('calendarPopup').classList.toggle('hidden')};
$('guestField').onclick=e=>{if(e.target.closest('.counter'))return;closePopups('guestsPopup');$('guestsPopup').classList.toggle('hidden')};
document.querySelectorAll('.counter button').forEach(b=>b.onclick=e=>{e.stopPropagation();let t=b.dataset.type,c=+b.dataset.change;if(t==='adults')adults=Math.max(1,adults+c);if(t==='children')children=Math.max(0,children+c);if(t==='rooms')rooms=Math.max(1,rooms+c);$('adultCount').textContent=adults;$('childCount').textContent=children;$('roomCount').textContent=rooms;$('guestText').textContent=`${adults} adults · ${children} children · ${rooms} room${rooms>1?'s':''}`});
function renderDays(el,year,month){let first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();el.innerHTML='';for(let i=0;i<first;i++)el.innerHTML+='<span class="day muted"></span>';for(let d=1;d<=days;d++){let s=document.createElement('span');s.className='day btn';s.textContent=d;s.dataset.date=`${year}-${month+1}-${d}`;s.onclick=()=>pickDate(s);el.appendChild(s)}}
function pickDate(s){let d=s.dataset.date;if(!selectedStart||selectedEnd){selectedStart=d;selectedEnd=null;document.querySelectorAll('.day').forEach(x=>x.classList.remove('selected','range'));$('dateText').textContent='Mon, Sep 1 — Check-out date'}else{selectedEnd=d;document.querySelectorAll('.day').forEach(x=>{if(x.dataset.date===selectedStart||x.dataset.date===selectedEnd)x.classList.add('selected')});$('dateText').textContent='Mon, Sep 1 — Wed, Sep 3'}if(selectedStart&&selectedEnd)$('calendarPopup').classList.remove('hidden')}
renderDays($('augDays'),2025,7);renderDays($('sepDays'),2025,8);
</script>
